import json
from playwright.sync_api import sync_playwright,expect
from play_qa_support import AppServer,Report,browser,timed_page,advance,snapshot,upgrade_and_offline,enable_survival,enter_lab,unlock_all
server=AppServer();report=Report('v2-save-qa');CONSENT='marie-world:v2:consent';DATA='marie-world:v2:save'
def open_save(pg):
 if not pg.locator('#savePanel').evaluate('el=>el.open'):pg.locator('#savePanel>summary').click()
def confirm(pg):expect(pg.locator('#saveDialog')).to_be_visible();pg.locator('#saveConfirm').click()
def import_file(pg,data,name='game.json'):pg.locator('#saveImport').set_input_files({'name':name,'mimeType':'application/json','buffer':data.encode()})
with sync_playwright() as p:
 b=browser(p);c,pg=timed_page(b,server,report);open_save(pg);assert pg.evaluate('localStorage.length')==0;pg.locator('#saveEnable').click();pg.locator('#saveCancel').click();assert pg.evaluate('localStorage.length')==0;report.passed('first visit and cancelled consent make zero storage writes; file backup remains available')
 enable_survival(pg);unlock_all(pg);pg.locator('#constructionDetails>summary').click();pg.locator('[data-build=greenhouse]').click();pg.locator('[data-build=recycler]').click();pg.locator('[data-mission=observe]').click();pg.locator('#labPause').click();pg.locator('[data-panel=home]').click();open_save(pg);before=snapshot(pg);pg.locator('#saveEnable').click();confirm(pg);expect(pg.locator('#saveEnable')).to_have_attribute('aria-pressed','true');raw=pg.evaluate('(key)=>localStorage.getItem(key)',DATA);saved=json.loads(raw);assert saved['schemaVersion']==2;assert len(saved['game']['installed'])==2;assert not any(k in saved['game'] for k in ['feed','canon','body','playLog']);pg.reload();expect(pg.locator('#saveStatus')).to_contain_text('복원');after=snapshot(pg)
 for key in ['resources','research','progress','modules','exploration','missions','processedEventIds']:assert after[key]==before[key],key
 assert after['session']['auto']==False;assert after['session']['crewAutomation']==False
 report.passed('real mission/research/two-facility game autosaves after consent and restores on reload with pending mission, receipts and paused time')
 open_save(pg);before=snapshot(pg);bad=json.loads(raw);bad['game']['day']=0;import_file(pg,json.dumps(bad));expect(pg.locator('#saveStatus')).to_contain_text('손상');assert snapshot(pg)==before;assert pg.evaluate('(key)=>localStorage.getItem(key)',DATA)==raw
 with pg.expect_download() as pending:pg.locator('#saveExport').click()
 pending.value.save_as(report.out/'game-backup.json');backup=(report.out/'game-backup.json').read_text();assert json.loads(backup)['game']['installed']==saved['game']['installed'];report.passed('actual JSON download contains game-only data; damaged import cannot change memory or previous save')
 pg.locator('#saveEnable').click();assert pg.evaluate('(key)=>localStorage.getItem(key)',CONSENT) is None;enter_lab(pg);pg.locator('#missionWithdraw').click();pg.locator('[data-panel=home]').click();open_save(pg);pg.locator('#saveLoad').click();confirm(pg);assert snapshot(pg)['exploration']['active'] is not None;assert pg.evaluate('(key)=>localStorage.getItem(key)',DATA)==raw;expect(pg.locator('#saveEnable')).to_have_attribute('aria-pressed','false')
 pg.evaluate("localStorage.setItem('unrelated-app','keep')");pg.locator('#saveDelete').click();confirm(pg);assert pg.evaluate('(key)=>localStorage.getItem(key)',DATA) is None;assert pg.evaluate("localStorage.getItem('unrelated-app')")=='keep';before=snapshot(pg);import_file(pg,backup);pg.locator('#saveCancel').click();assert snapshot(pg)==before;import_file(pg,backup);confirm(pg);assert snapshot(pg)['modules']['installed']==after['modules']['installed'];assert pg.evaluate('(key)=>localStorage.getItem(key)',DATA) is None;report.passed('disable keeps manual load usable without overwrite; delete touches only app keys; file cancel/import stays nonpersistent')
 pg.reload();assert snapshot(pg)['mode']=='healing';assert snapshot(pg)['modules']['installed']=={};assert pg.evaluate("localStorage.getItem('unrelated-app')")=='keep';open_save(pg);pg.locator('#savePanel').screenshot(path=str(report.out/'desktop-save.png'))
 pg.evaluate('([c,d])=>{localStorage.setItem(c,"yes");localStorage.setItem(d,"{broken");}',[CONSENT,DATA]);pg.reload();expect(pg.locator('#saveStatus')).to_contain_text('손상');advance(pg,30);pg.evaluate("window.dispatchEvent(new Event('pagehide'))");assert pg.evaluate('(key)=>localStorage.getItem(key)',DATA)=='{broken';open_save(pg);pg.locator('#saveNow').click();assert json.loads(pg.evaluate('(key)=>localStorage.getItem(key)',DATA))['schemaVersion']==2;c.close();report.passed('deleted/off state restarts fresh; corrupt boot disables automatic writes even on pagehide, explicit save can recover')
 for w,h in [(768,1024),(390,844)]:
  c,m=timed_page(b,server,report,w,h);open_save(m);m.locator('#saveEnable').tap();confirm(m);assert m.evaluate('document.documentElement.scrollWidth<=innerWidth');m.locator('#savePanel').screenshot(path=str(report.out/f'save-{w}.png'));m.locator('#saveDelete').tap();confirm(m);c.close()
 report.passed('tablet/mobile consent, file controls, delete and no overflow (emulated)')
 c,f=timed_page(b,server,report,1440,1800);f.locator('#flightViewBtn').click();f.locator('#flightCanvas').scroll_into_view_if_needed();advance(f,3);open_save(f);f.locator('#saveEnable').click();before=f.locator('#flightDistance').inner_text();advance(f,5);assert f.locator('#flightDistance').inner_text()==before;f.locator('#saveCancel').click();f.locator('#flightCanvas').scroll_into_view_if_needed();advance(f,2);assert f.locator('#flightDistance').inner_text()!=before;c.close();report.passed('native save confirmation pauses Flight model/render lifecycle and cancellation resumes safely')
 c=b.new_context();c.add_init_script("Object.defineProperty(window,'localStorage',{get(){throw new DOMException('blocked','SecurityError')}})");blocked=c.new_page();report.wire(blocked);blocked.goto(server.url);open_save(blocked);expect(blocked.locator('#saveEnable')).to_be_disabled();expect(blocked.locator('#saveDelete')).to_be_disabled()
 with blocked.expect_download():blocked.locator('#saveExport').click()
 c.close();report.passed('blocked browser storage leaves validated file backup available without page errors')
 c,o=upgrade_and_offline(b,server,report);open_save(o);import_file(o,backup);confirm(o);assert len(snapshot(o)['modules']['installed'])==2;assert snapshot(o)['session']['auto']==False;report.passed('after old-worker consent upgrade and offline reload, actual JSON restores inventory/research/facilities/active mission')
 with o.expect_download():o.locator('#saveExport').click()
 c.close();b.close()
report.finish();server.close()
